// Author: MiYu. Source blight masks update bounded visible terrain chunks without rebuilding static terrain or atlases.
#include "terrain_scene.h"
#include <algorithm>

namespace war3 {
void TerrainScene::initializeBlight(const std::vector<TerrainCell>& cells) {
    std::string type;switch(source_.tileset){case 'A':type="Ashen";break;case 'B':type="Barrens";break;case 'C':type="Felwood";break;case 'D':type="Cave";break;case 'F':type="Lordf";break;case 'G':type="Dungeon";break;case 'I':type="Ice";break;case 'J':type="DRuins";break;case 'K':type="Citadel";break;case 'L':type="Lords";break;case 'N':type="North";break;case 'O':type="Outland";break;case 'Q':type="VillageFall";break;case 'V':case 'X':case 'Y':type="Village";break;case 'W':type="Lordw";break;case 'Z':type="Ruins";break;default:throw std::runtime_error("Unsupported source blight tileset");}blightTexture_="TerrainArt\\Blight\\"+type+"_Blight.blp";auto& image=assets_.image(blightTexture_);if((image.width!=256 && image.width!=512) || image.height!=256)throw std::runtime_error("Unexpected source blight atlas dimensions");blightWidth_=image.width;blightHeight_=image.height;
    blightSeen_=world_.blightChunks();blightChunks_.resize(blightSeen_.size());blightCells_.resize(blightSeen_.size());unsigned columns=(source_.width-2)/16+1;for(auto& cell:cells){auto index=(cell.y/16)*columns+cell.x/16;blightCells_[index].push_back(cell);for(auto corner:cell.corners)blightChunks_[index].bounds.add(source_.origin[0]+float(corner%source_.width)*128,source_.origin[1]+float(corner/source_.width)*128,surface_[corner]);}for(unsigned i=0;i<blightChunks_.size();++i){assets_.check();rebuildBlight(i);if(!blightChunks_[i].indices.empty())initialBlightUploads_.push_back(i);}
}
void TerrainScene::rebuildBlight(unsigned index) {
    auto& target=blightChunks_.at(index);meshBytes_-=target.vertices.size()*sizeof(SceneVertex)+target.indices.size()*4;target.vertices.clear();target.indices.clear();target.vertexBuffer.Reset();target.indexBuffer.Reset();target.texture=blightTexture_;constexpr unsigned bits[]={2,8,4,1};constexpr float uv[4][2]={{0,1},{0,0},{1,0},{1,1}};constexpr std::uint32_t triangles[]={0,3,1,1,3,2};
    for(auto& cell:blightCells_[index]){unsigned mask=0;for(unsigned i=0;i<4;++i)if(cell.blightable[i] && (source_.corners[cell.corners[i]].flags&0x20))mask|=bits[i];if(!mask)continue;unsigned tile=mask;if(mask==15 && blightWidth_==512 && cell.variation<16)tile=16+cell.variation;float sx=float(tile<16?tile%4*64:(4+(tile-16)%4)*64)+.5f,sy=float(tile<16?tile/4*64:(tile-16)/4*64)+.5f;std::array<SceneVertex,4> vertices;for(unsigned i=0;i<4;++i){auto corner=cell.corners[i];vertices[i]={source_.origin[0]+float(corner%source_.width)*128,source_.origin[1]+float(corner/source_.width)*128,surface_[corner],0xffffffff,(sx+uv[i][0]*63)/blightWidth_,(sy+uv[i][1]*63)/blightHeight_};}append(target,vertices,triangles);}blightSeen_[index]=world_.blightChunks()[index];
}
size_t TerrainScene::drawBlight(Renderer& renderer,const DirectX::XMMATRIX& viewProjection) {
    auto device=renderer.device();device->SetRenderState(D3DRS_ALPHABLENDENABLE,TRUE);device->SetRenderState(D3DRS_ZWRITEENABLE,FALSE);device->SetTexture(0,assets_.texture(blightTexture_));size_t visible=0;unsigned updated=0;auto deadline=GetTickCount64()+3;
    for(unsigned i=0;i<blightChunks_.size();++i){auto& chunk=blightChunks_[i];if(blightCells_[i].empty() || !chunk.bounds.visible(viewProjection))continue;if(blightSeen_[i]!=world_.blightChunks()[i] && updated<4 && GetTickCount64()<deadline){rebuildBlight(i);if(!chunk.indices.empty())uploadChunk(renderer,chunk);++updated;}if(chunk.indices.empty())continue;if(!chunk.vertexBuffer || !chunk.indexBuffer)throw std::runtime_error("Blight GPU upload incomplete");device->SetStreamSource(0,chunk.vertexBuffer.Get(),0,sizeof(SceneVertex));device->SetIndices(chunk.indexBuffer.Get());auto result=device->DrawIndexedPrimitive(D3DPT_TRIANGLELIST,0,0,UINT(chunk.vertices.size()),0,UINT(chunk.indices.size()/3));if(FAILED(result))throw std::runtime_error("Draw blight region failed");++visible;}
    device->SetRenderState(D3DRS_ALPHABLENDENABLE,FALSE);device->SetRenderState(D3DRS_ZWRITEENABLE,TRUE);return visible;
}
}
